#!/usr/bin/env bash
# Crea etiquetas, milestones e issues (uno por HU) en el repositorio actual.
# Requisito: gh auth login. Uso: bash scripts/crear_issues_github.sh
set -e

gh label create "Must" --color 1F4E79 --force
gh label create "Should" --color 3A8E5C --force
gh label create "Could" --color E07B39 --force
gh label create "Won't" --color 8C8C8C --force
gh label create "E1 Catálogo y pedidos" --color BFD4F2 --force
gh label create "E2 Pagos" --color BFD4F2 --force
gh label create "E3 Seguimiento y despacho" --color BFD4F2 --force
gh label create "E4 Inventario y reportes" --color BFD4F2 --force
gh label create "E5 Cuentas y fidelización" --color BFD4F2 --force
gh label create "historia-usuario" --color 5319E7 --force
gh api repos/{owner}/{repo}/milestones -f title="Sprint 1" >/dev/null 2>&1 || true
gh api repos/{owner}/{repo}/milestones -f title="Sprint 2" >/dev/null 2>&1 || true
gh api repos/{owner}/{repo}/milestones -f title="Sprint 3" >/dev/null 2>&1 || true

gh issue create --title "HU-01 Registrarme e iniciar sesión con mi correo o número de celular" --body "$(printf 'Como cliente, quiero registrarme e iniciar sesión con mi correo o número de celular, para hacer pedidos sin volver a escribir mis datos cada vez.\n\n**Prioridad:** Must | WSJF 10.50 (CoD 21 / 2 SP)\n**Requisito de origen (Tema 1):** RF01\n**Dependencias:** —\n**Criterios de aceptación:** features/HU-01*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E5 Cuentas y fidelización" --milestone "Sprint 1"
gh issue create --title "HU-04 Ver el monto total de mi pedido con el costo de envío cuando elijo delivery" --body "$(printf 'Como cliente, quiero ver el monto total de mi pedido con el costo de envío cuando elijo delivery, para saber cuánto voy a pagar antes de confirmar.\n\n**Prioridad:** Must | WSJF 10.00 (CoD 20 / 2 SP)\n**Requisito de origen (Tema 1):** RF04\n**Dependencias:** HU-03\n**Criterios de aceptación:** features/HU-04*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E1 Catálogo y pedidos" --milestone "Sprint 1"
gh issue create --title "HU-12 Asignar cada pedido de delivery a un repartidor disponible" --body "$(printf 'Como cajero, quiero asignar cada pedido de delivery a un repartidor disponible, para que ningún pedido quede sin entregar.\n\n**Prioridad:** Must | WSJF 9.50 (CoD 19 / 2 SP)\n**Requisito de origen (Tema 1):** RF07, RF10\n**Dependencias:** HU-07\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E3 Seguimiento y despacho" --milestone "Sprint 2"
gh issue create --title "HU-02 Ver el catálogo de productos con su precio y si hay disponibilidad" --body "$(printf 'Como cliente, quiero ver el catálogo de productos con su precio y si hay disponibilidad, para saber qué puedo pedir antes de ir o llamar a la panadería.\n\n**Prioridad:** Must | WSJF 9.00 (CoD 27 / 3 SP)\n**Requisito de origen (Tema 1):** RF02\n**Dependencias:** —\n**Criterios de aceptación:** features/HU-02*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E1 Catálogo y pedidos" --milestone "Sprint 1"
gh issue create --title "HU-10 Ver la dirección y el número de contacto del cliente del pedido que me asignaron" --body "$(printf 'Como repartidor, quiero ver la dirección y el número de contacto del cliente del pedido que me asignaron, para entregar sin pedir los datos por WhatsApp.\n\n**Prioridad:** Must | WSJF 8.50 (CoD 17 / 2 SP)\n**Requisito de origen (Tema 1):** RF10\n**Dependencias:** HU-12\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E3 Seguimiento y despacho" --milestone "Sprint 2"
gh issue create --title "HU-07 Ver los pedidos entrantes y actualizar su estado desde el panel de gestión" --body "$(printf 'Como cajero, quiero ver los pedidos entrantes y actualizar su estado desde el panel de gestión, para organizar la preparación y dejar de anotar pedidos en papel.\n\n**Prioridad:** Must | WSJF 7.67 (CoD 23 / 3 SP)\n**Requisito de origen (Tema 1):** RF07\n**Dependencias:** HU-05\n**Criterios de aceptación:** features/HU-07*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E3 Seguimiento y despacho" --milestone "Sprint 1"
gh issue create --title "HU-05 Elegir el método de pago (efectivo, Yape o Plin) y recibir un número de pedido único" --body "$(printf 'Como cliente, quiero elegir el método de pago (efectivo, Yape o Plin) y recibir un número de pedido único, para tener la confirmación de que mi pedido fue registrado.\n\n**Prioridad:** Must | WSJF 5.40 (CoD 27 / 5 SP)\n**Requisito de origen (Tema 1):** RF05\n**Dependencias:** HU-04, HU-01\n**Criterios de aceptación:** features/HU-05*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E2 Pagos" --milestone "Sprint 1"
gh issue create --title "HU-03 Armar un pedido eligiendo productos, cantidades y el tipo de entrega (recojo o delivery)" --body "$(printf 'Como cliente, quiero armar un pedido eligiendo productos, cantidades y el tipo de entrega (recojo o delivery), para pedir sin llamar y sin que mi pedido se anote mal.\n\n**Prioridad:** Must | WSJF 5.20 (CoD 26 / 5 SP)\n**Requisito de origen (Tema 1):** RF03\n**Dependencias:** HU-02\n**Criterios de aceptación:** features/HU-03*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E1 Catálogo y pedidos" --milestone "Sprint 1"
gh issue create --title "HU-08 Que al confirmarse un pedido se descuenten automáticamente los insumos según la receta de cada producto" --body "$(printf 'Como propietaria, quiero que al confirmarse un pedido se descuenten automáticamente los insumos según la receta de cada producto, para saber cuánta harina, azúcar y mantequilla me queda sin contarla a mano.\n\n**Prioridad:** Must | WSJF 4.20 (CoD 21 / 5 SP)\n**Requisito de origen (Tema 1):** RF08\n**Dependencias:** HU-05\n**Criterios de aceptación:** features/HU-08*.feature\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Must" --label "E4 Inventario y reportes" --milestone "Sprint 2"
gh issue create --title "HU-11 Consultar el stock de insumos en tiempo real y recibir una alerta cuando uno baje del mínimo" --body "$(printf 'Como propietaria, quiero consultar el stock de insumos en tiempo real y recibir una alerta cuando uno baje del mínimo, para comprar a tiempo y no quedarme sin insumos el fin de semana.\n\n**Prioridad:** Should | WSJF 6.33 (CoD 19 / 3 SP)\n**Requisito de origen (Tema 1):** Obj. negocio 3\n**Dependencias:** HU-08\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Should" --label "E4 Inventario y reportes" --milestone "Sprint 3"
gh issue create --title "HU-06 Recibir avisos del estado de mi pedido (recibido, en preparación, en camino, entregado)" --body "$(printf 'Como cliente, quiero recibir avisos del estado de mi pedido (recibido, en preparación, en camino, entregado), para no tener que llamar para preguntar por mi pedido.\n\n**Prioridad:** Should | WSJF 5.67 (CoD 17 / 3 SP)\n**Requisito de origen (Tema 1):** RF06\n**Dependencias:** HU-07\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Should" --label "E3 Seguimiento y despacho" --milestone "Sprint 2"
gh issue create --title "HU-09 Obtener un reporte diario de ventas y pedidos pendientes" --body "$(printf 'Como propietaria, quiero obtener un reporte diario de ventas y pedidos pendientes, para hacer el cierre de caja en minutos.\n\n**Prioridad:** Should | WSJF 5.33 (CoD 16 / 3 SP)\n**Requisito de origen (Tema 1):** RF09\n**Dependencias:** HU-05\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Should" --label "E4 Inventario y reportes" --milestone "Sprint 2"
gh issue create --title "HU-13 Programar mi pedido para una fecha y hora futura" --body "$(printf 'Como cliente, quiero programar mi pedido para una fecha y hora futura, para asegurar mi pan del fin de semana aunque la panadería esté cerrada.\n\n**Prioridad:** Should | WSJF 4.40 (CoD 22 / 5 SP)\n**Requisito de origen (Tema 1):** Obj. negocio 1\n**Dependencias:** HU-03\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Should" --label "E1 Catálogo y pedidos" --milestone "Sprint 3"
gh issue create --title "HU-14 Repetir un pedido anterior con un solo botón" --body "$(printf 'Como cliente frecuente, quiero repetir un pedido anterior con un solo botón, para pedir más rápido lo que siempre compro.\n\n**Prioridad:** Could | WSJF 6.00 (CoD 12 / 2 SP)\n**Requisito de origen (Tema 1):** Obj. negocio 4\n**Dependencias:** HU-03, HU-01\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Could" --label "E5 Cuentas y fidelización" --milestone "Sprint 3"
gh issue create --title "HU-15 Acumular puntos por mis compras y canjearlos por productos" --body "$(printf 'Como cliente frecuente, quiero acumular puntos por mis compras y canjearlos por productos, para sentir que la panadería premia mi preferencia.\n\n**Prioridad:** Won't | WSJF 1.80 (CoD 9 / 5 SP)\n**Requisito de origen (Tema 1):** Obj. negocio 4\n**Dependencias:** HU-01, HU-05\n**Criterios de aceptación:** ver backlog/product_backlog.md\n**DoD:** docs/DoR_DoD.md')" --label "historia-usuario" --label "Won't" --label "E5 Cuentas y fidelización"
